                                                                       "fvalue=mp(mm('ffvelcdm',{'A':x,'B':'CC','F':'F','C':'x'}),both(ftype,hx))\n"
                                                                       '    '
                                                                       'ztype=implies(condition,hz);ftypepoint=implies(condition,fvalue)\n'
                                                                       '    '
                                                                       "dtype=implies(condition,mp(mm('subcl',{'A':'Z','B':fx}),both(hz,fvalue)))\n"
                                                                       '    '
                                                                       "areal=implies(condition,mp(mm('abscl',{'A':difference}),mp(mm('subcl',{'A':'Z','B':fx}),both(hz,fvalue))))\n"
                                                                       '    ereal=implies(condition,he)\n'
                                                                       '    '
                                                                       "ecomplex=mp(mm('recn',{'A':'E'}),he)\n"
                                                                       '    '
                                                                       'ectype=implies(condition,ecomplex)\n'
                                                                       '    '
                                                                       "measurable=mp(mm('iccmbl'),realpair)\n"
                                                                       '    '
                                                                       "volume_real=mp(mm('iccvolcl'),realpair)\n"
                                                                       '    '
                                                                       "volume=mp(mm('volicc'),both(ha,hb,hab))\n"
                                                                       '    '
                                                                       "zint0=mp(mm('iblconst',{'A':x,'B':'Z'}),both(measurable,volume_real,hz))\n"
                                                                       '    '
                                                                       "zint=rewrite(mm('fconstmpt',{'A':x,'B':'Z'}),zint0)\n"
                                                                       '    '
                                                                       "eint0=mp(mm('iblconst',{'A':x,'B':'E'}),both(measurable,volume_real,ecomplex))\n"
                                                                       '    '
                                                                       "eint=rewrite(mm('fconstmpt',{'A':x,'B':'E'}),eint0)\n"
                                                                       '    '
                                                                       "fwhole=mp(mm('cniccibl'),both(ha,hb,hf))\n"
                                                                       '    '
                                                                       "fmpt=unlift(mm('feqmptd',{'ph':'T.','A':x,'B':'CC','F':'F'},(lift(ftype),)))\n"
                                                                       '    fint=rewrite(fmpt,fwhole)\n'
                                                                       '    '
                                                                       "dint=unlift(mm('iblsub',{'ph':'T.','A':x,'B':'Z','C':fx,'V':'CC'},(ztype,lift(zint),ftypepoint,lift(fint))))\n"
                                                                       '    '
                                                                       "aint=unlift(mm('iblabs',{'ph':'T.','A':x,'B':difference,'V':'CC'},(dtype,lift(dint))))\n"
                                                                       '    '
                                                                       "first=unlift(mm('itgabs',{'ph':'T.','A':x,'B':difference,'V':'CC'},(dtype,lift(dint))))\n"
                                                                       '    '
                                                                       "second=unlift(mm('itgle',{'ph':'T.','A':x,'B':absolute,'C':'E'},(lift(aint),lift(eint),areal,ereal,bound)))\n"
                                                                       "    idiff=f'S. {x} {difference} _d "
                                                                       "x';iabs=f'S. {x} {absolute} _d "
                                                                       "x';ieta=f'S. {x} E _d x'\n"
                                                                       '    '
                                                                       "idiff_type=unlift(mm('itgcl',{'ph':'T.','A':x,'B':difference,'V':'CC'},(dtype,lift(dint))))\n"
                                                                       '    '
                                                                       "left_type=mp(mm('abscl',{'A':idiff}),idiff_type)\n"
                                                                       '    '
                                                                       "middle_type=unlift(mm('itgrecl',{'ph':'T.','A':x,'B':absolute},(areal,lift(aint))))\n"
                                                                       '    '
                                                                       "right_type=unlift(mm('itgrecl',{'ph':'T.','A':x,'B':'E'},(ereal,lift(eint))))\n"
                                                                       "    trans=mp(mp(mm('letr',{'A':f'( "
                                                                       'abs ` {idiff} '
                                                                       ")','B':iabs,'C':ieta}),both(left_type,middle_type,right_type)),both(first,second))\n"
                                                                       '    '
                                                                       "split=unlift(mm('itgsub',{'ph':'T.','A':x,'B':'Z','C':fx,'V':'CC'},(ztype,lift(zint),ftypepoint,lift(fint))))\n"
                                                                       '    '
                                                                       "integral_z=mp(mm('itgconst',{'A':x,'B':'Z'}),both(measurable,volume_real,hz))\n"
                                                                       '    '
                                                                       "integral_e=mp(mm('itgconst',{'A':x,'B':'E'}),both(measurable,volume_real,ecomplex))\n"
                                                                       '    '
                                                                       'result=rewrite(volume,rewrite(integral_e,rewrite(integral_z,rewrite(split,trans))))\n'
                                                                       '    '
                                                                       'formula,hypotheses=infer(result)\n'
                                                                       "    expected=f'|- ( abs ` ( ( Z x. ( "
                                                                       'B - A ) ) - S. {x} {fx} _d x ) ) <_ '
                                                                       "( E x. ( B - A ) )'\n"
                                                                       "    expected_h=frozenset(('|- A e. "
                                                                       "RR','|- B e. RR','|- A <_ B',f'|- F "
                                                                       "e. ( {x} -cn-> CC )','|- Z e. "
                                                                       "CC','|- E e. RR',f'|- ( ( T. /\\\\ x "
                                                                       "e. {x} ) -> {absolute} <_ E )'))\n"
                                                                       '    if formula!=expected or '
