                                                                         '    '
                                                                         "cp=('iff_mp',mp(mm('elicc2',{'A':'A','B':'B','C':'C'}),realpair),hc,0)\n"
                                                                         '    '
                                                                         "dp=('iff_mp',mp(mm('elicc2',{'A':'A','B':'B','C':'D'}),realpair),hd,0)\n"
                                                                         '    '
