                                                                          '    '
                                                                          "restricted=mp(mm('ovres',{'A':'U','B':'V','C':domain,'D':domain,'F':full}),both(hu,hv))\n"
                                                                          '    '
                                                                          "distance=mp(mm('cnmetdval',{'A':'U','B':'V','D':full},(eqref(full),)),both(uc,vc))\n"
                                                                          '    '
                                                                          'result=rewrite(distance,restricted)\n'
                                                                          '    '
                                                                          'formula,hypotheses=infer(result)\n'
                                                                          "    if formula!=f'|- ( U {c} V ) "
                                                                          "= ( abs ` ( U - V ) )' or "
                                                                          'hypotheses!=frozenset(infer(p)[0] '
                                                                          'for p in (ha,hb,hu,hv)):\n'
                                                                          '        raise '
                                                                          "ProofError('interval_distance_scope')\n"
                                                                          '    '
                                                                          "ft=mp(mm('cncff',{'A':domain,'B':'CC','F':'F'}),hf)\n"
                                                                          '    '
                                                                          "fu=mp(mm('ffvelcdm',{'A':domain,'B':'CC','F':'F','C':'U'}),both(ft,hu));fv=mp(mm('ffvelcdm',{'A':domain,'B':'CC','F':'F','C':'V'}),both(ft,hv))\n"
                                                                          "    ir=mp(mm('ovres',{'A':'( F ` "
                                                                          "U )','B':'( F ` V "
                                                                          ")','C':'CC','D':'CC','F':full}),both(fu,fv))\n"
                                                                          '    '
                                                                          "idist=mp(mm('cnmetdval',{'A':'( F "
                                                                          "` U )','B':'( F ` V "
                                                                          ")','D':full},(eqref(full),)),both(fu,fv))\n"
