                                                                        "ft=mp(mm('cncff',{'A':whole,'B':'CC','F':'F'}),hf)\n"
                                                                        '    '
                                                                        "fmap=unlift(mm('feqmptd',{'ph':'T.','A':whole,'B':'CC','F':'F'},(lift(ft),)))\n"
                                                                        '    '
                                                                        'integrable=rewrite(fmap,integrable)\n'
                                                                        "    condition=f'|- ( T. /\\\\ x e. "
                                                                        '{whole} '
                                                                        ")';xin=conjunct(assumption(condition),1)\n"
                                                                        '    '
                                                                        "fx_type=mp(mm('ffvelcdm',{'A':whole,'B':'CC','F':'F','C':'x'}),both(ft,xin))\n"
                                                                        '    '
                                                                        "result=unlift(mm('itgcl',{'ph':'T.','A':whole,'B':fx,'V':'CC'},(implies(condition,fx_type),lift(integrable))))\n"
                                                                        '    '
                                                                        'formula,hypotheses=infer(result)\n'
