                                                                        '    '
                                                                        "expect_raw(finite_sum_append_certificate(),'|- "
                                                                        'sum_ k e. ( 1 ... ( N + 1 ) ) ( H ` '
                                                                        'k ) = ( sum_ k e. ( 1 ... N ) ( H ` '
                                                                        "k ) + ( H ` ( N + 1 ) ) )',{'|- N "
                                                                        "e. NN','|- ( ( T. /\\\\ k e. ( 1 "
                                                                        '... ( N + 1 ) ) ) -> ( H ` k ) e. '
                                                                        "CC )'})\n"
                                                                        '    '
                                                                        "first,old,last=sp.symbols('first "
                                                                        "old last')\n"
                                                                        '    if '
                                                                        'sp.expand(base_coefficient*first-first)!=0 '
                                                                        'or '
                                                                        'sp.expand(old+append_coefficient*last-(old+last))!=0:raise '
                                                                        "ProofError('finite_sum_translation_induction')\n"
                                                                        "    if mode=='right':\n"
                                                                        '        '
                                                                        "expect_raw(cell_right_endpoint_certificate(),'|- "
                                                                        "D e. ( C [,] D )',{'|- C e. RR','|- "
                                                                        "D e. RR','|- C <_ D'})\n"
                                                                        '        summand=right_sum()[4]\n'
                                                                        '        '
                                                                        "expected=fn('mul',fn('eval',F,fn('add',A,fn('mul',v('j'),fn('div',L,N)))),fn('div',L,N))\n"
                                                                        "    elif mode=='weighted':\n"
                                                                        '        '
                                                                        "expect_raw(weighted_value_certificate(),'|- "
                                                                        '( ( z e. ( A [,] B ) |-> ( ( G ` z '
                                                                        ') x. ( F ` z ) ) ) ` U ) = ( ( G ` '
                                                                        "U ) x. ( F ` U ) )',{'|- F e. ( ( A "
                                                                        "[,] B ) -cn-> CC )','|- G e. ( ( A "
                                                                        "[,] B ) -cn-> CC )','|- U e. ( A "
                                                                        "[,] B )'})\n"
                                                                        '        summand=weighted_sum()[4]\n'
                                                                        '        '
                                                                        "expected=fn('mul',fn('mul',fn('eval',G,fn('eval',T,v('j'))),fn('eval',H,fn('eval',T,v('j')))),fn('div',L,N))\n"
                                                                        '    else:raise '
                                                                        "ProofError('finite_sum_translation_mode')\n"
                                                                        '    if summand!=expected:raise '
                                                                        "ProofError('finite_sum_translation_summand')\n"
